"""
Command based collectors with user-defined commands.

Classes:

- :class:`ConfigurableCommandCollector`: configurable command based collector
- :class:`ConfigurableStartableCommandCollector`: configurable startable command based collector
"""
from abc import ABCMeta
import logging
import os.path
import six
from .collector import CommandCollector
from .startable import StartableObject

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@six.add_metaclass(ABCMeta)
class ConfigurableCommandCollector(CommandCollector):
    """
    Configurable command based collector.

    Execute shell commands on the remote host to optionally generate and find the files,
    that shall be transferred to the localhost ("find_command").

    Optionally map remote paths to local paths via a locally executed command ("map_command").

    Transfer the files from remote host to local host.

    Optionally postprocess the transferred files on the local host ("postprocess_command").

    Optionally cleanup files on the remote host ("cleanup_command").
    """

    def __init__(self,
                 find_command,
                 map_command=None,
                 postprocess_command=None,
                 cleanup_command=None,
                 **kwargs):
        """
        Create a configurable command based collector.

        :param str find_command:
            command to optionally generate and/or preprocess and mandatorily find generated files on remote host
            (each source path as one line in stdout)
        :param str map_command:
            command to map a source path on the remote host to a target path on the local host
            relatively to the subdirectory for this collector in the target directory given to collect()
            (reads one line with source path from stdin and writes one line with target path to stdout)
        :param str postprocess_command:
            command to postprocess transferred files
            (executed in the subdirectory for this collector in the target directory given to collect())
        :param str cleanup_command:
            command to clean up temporary files on the remote host
        """
        super(ConfigurableCommandCollector, self).__init__(**kwargs)
        self._find_command = find_command
        self._map_command = map_command
        self._postprocess_command = postprocess_command
        self._cleanup_command = cleanup_command

    def _collect(self, target_dir):
        """
        Collect information from remote hosts.

        On the remote host, the information to be collected might first need
        to be generated (e. g. snapshot or journal) as files.

        On the remote host, the filenames of the files, that need to be
        transferred, need to be calculated/found (e. g. the last created file in a directory).

        On the remote host, the found files might need to be preprocessed
        (e. g. compressed, packed or converted into a different format) before it will
        be transferred.

        The preprocessed files on the remote host must be transferred to the
        local host.

        On the local host, the information might need to be postprocessed
        (e. g. compressed, unpacked, uncompressed).

        On the remote host, any intermediately created files need to be cleaned
        up.

        :param str target_dir:
            target directory, where collected information shall be stored on the local host
            (subdirectory for this collector in the target directory given to collect())
        """
        source_paths = self._find()
        target_paths = self._map(source_paths)
        self._transfer(
            source_paths=source_paths,
            target_paths=target_paths,
            target_dir=target_dir)
        self._postprocess(target_dir)
        self._cleanup()

    def _find(self):
        """
        Find the files, that shall be collected on the remote host.

        Optionally generate and/or preprocess and mandatorily find generated files on remote host.

        :return: source paths to be transferred
        :rtype: list(bytes)
        """
        logger.debug("finding")
        source_paths = self._tool_executor.execute(
            command=self._find_command.encode()).decode().strip().split("\n")
        logger.debug("source paths=%r", source_paths)
        return source_paths

    def _map(self, source_paths):
        """
        Map source paths on remote host to target paths on local host.

        If no map_command was specified, each source path is mapped to its basename.

        :param list(bytes) source_paths: source paths
        :return:  target paths
        :rtype: list(bytes)
        """
        logger.debug("mapping")
        if self._map_command is None:
            target_paths = [os.path.basename(source_path) for source_path in source_paths]
        else:
            process = self._local_executor.start(command=self._map_command.encode())
            for source_path in source_paths:
                process.stdin.write("{source_path}\n".format(source_path=source_path).encode())
            process.stdin.close()
            target_paths = []
            for line in process.stdout:
                target_paths.append(line.strip().decode())
        logger.debug("target paths=%r", target_paths)
        return target_paths

    def _transfer(self, source_paths, target_paths, target_dir):
        """
        Transfer the files, that shall be collected, from the remote host
        to the local host.

        :param list(bytes) source_paths: list of source paths on remote host
        :param list(bytes) target_paths: list of target paths on local host relative to target_dir
        :param str target_dir:
            target directory, where collected files shall be stored on the local host
        """

        logger.debug("transferring")
        assert len(source_paths) == len(target_paths)
        assert all(source_paths)
        assert all(target_paths)
        for i in range(len(source_paths)):
            target_path = os.path.join(
                target_dir,
                target_paths[i])
            dir_name = os.path.dirname(target_path)
            self._create_dir(path=dir_name)
            self._file_getter.get_file(
                source_path=source_paths[i],
                target_path=target_path)

    def _postprocess(self, target_dir):
        """
        Postprocess the transferred files on the local.

        If no postprocess_command was specified, do nothing.

        :param str target_dir:
            target directory (subdirectory for this collector in the target directory given to collect())
        """
        logger.debug("postprocessing")
        if self._postprocess_command is not None:
            self._local_executor.execute(
                command="cd '{target_dir}' ; {command}".format(
                    target_dir=target_dir,
                    command=self._postprocess_command).encode())

    def _cleanup(self):
        """
        Cleanup on the remote host after the information, that shall be
        collected, has been transferred to the local host.

        If no cleanup_command was specified, no nothing.
        """
        logger.debug("cleaning up")
        if self._cleanup_command is not None:
            self._tool_executor.execute(command=self._cleanup_command.encode())


class ConfigurableStartableCommandCollector(StartableObject, ConfigurableCommandCollector):
    """
    Configurable startable command based collector.

    A configurable command based collector with additional commands to start and stop
    the generation of the information, that shall be collected.
    """

    def __init__(self, start_command, stop_command, **kwargs):
        """
        Create a configurable startable command based collector.

        :param str start_command: start command
        :param str stop_command: stop command,
        """
        super(ConfigurableStartableCommandCollector, self).__init__(**kwargs)
        self._start_command = start_command
        self._stop_command = stop_command

    def _start(self):
        """
        Start the generation of the information that shall be collected.
        """
        if self._start_command is not None:
            return self._tool_executor.execute(
                command=self._start_command.encode())

    def _stop(self):
        """
        Stop the generation of the information that shall be collected.
        """
        if self._stop_command is not None:
            return self._tool_executor.execute(
                command=self._stop_command.encode())
